provider "aws" {
  region              = var.primary_region
  allowed_account_ids = [var.account_id]
  default_tags { tags = merge(var.tags, { ManagedBy = "Terraform", Factory = var.name }) }
}

provider "aws" {
  alias               = "replica"
  region              = var.secondary_region
  allowed_account_ids = [var.account_id]
  default_tags { tags = merge(var.tags, { ManagedBy = "Terraform", Factory = var.name }) }
}

